// Census of every engine-provided identifier the shipped effect shaders use.
//
// The prelude is generated by the engine, not shipped in assets/, so the contract an
// author actually writes against is the set of identifiers that appear inside the
// shipped <shader> bodies. This extracts exactly that set, split by shader type and
// cross-referenced with the params the same effect declares.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

const root = process.argv[2];
const files = [];
(function walk(dir) {
  for (const n of readdirSync(dir)) {
    const p = join(dir, n);
    if (statSync(p).isDirectory()) walk(p);
    else if (n.toLowerCase().endsWith('.xml')) files.push(p);
  }
})(root);

const acIds = new Map(); // identifier -> { count, files:Set, types:Set }
const helpers = new Map(); // texture2D* / other calls
const paramRefs = new Map(); // occurrence counts of declared param ids inside shaders
const declaredNotUsed = [];
const usedNotDeclared = [];

const bump = (map, key) => {
  if (!map.has(key)) map.set(key, { count: 0, files: new Set(), types: new Set() });
  const e = map.get(key);
  e.count++;
  return e;
};

for (const f of files) {
  const src = readFileSync(f, 'utf8');
  const clean = src.replace(/<!--[\s\S]*?-->/g, '');
  // declared param ids
  const ids = new Set();
  for (const m of clean.matchAll(/<(spinner|slider|float|color|point|xyz|orient|hue-disc|hue-ring|selector|switch|texture)\b[^>]*\bid\s*=\s*"([^"]+)"/g)) ids.add(m[2]);

  for (const m of clean.matchAll(/<shader\b([^>]*)>([\s\S]*?)<\/shader>/g)) {
    const typeM = /type\s*=\s*"([^"]+)"/.exec(m[1]);
    const type = (typeM?.[1] ?? 'fragment').toLowerCase();
    const body = m[2];
    for (const idm of body.matchAll(/\b(ac[A-Z][A-Za-z0-9]*)\b/g)) {
      const e = bump(acIds, idm[1]);
      e.files.add(f);
      e.types.add(type);
    }
    for (const hm of body.matchAll(/\b(texture[A-Za-z0-9]*)\s*\(/g)) bump(helpers, hm[1]);
    // param id used as a bare identifier or via `.` access
    for (const id of ids) {
      const re = new RegExp(`\\b${id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'g');
      const n = (body.match(re) ?? []).length;
      if (n) paramRefs.set(id, (paramRefs.get(id) ?? 0) + n);
      else if (type === 'fragment') declaredNotUsed.push(`${f.split(/[\\/]/).pop()} :: ${id}`);
    }
    // identifiers that look like params but were not declared
    for (const um of body.matchAll(/\b([a-z][A-Za-z0-9_]{2,})\b/g)) {
      const name = um[1];
      if (/^(vec|mat|float|int|bool|void|return|if|else|for|while|uniform|varying|const|struct|true|false|in|out|void|highp|mediump|lowp|precision|sampler2D|main)$/.test(name)) continue;
      if (acIds.has(name)) continue;
      if (!ids.has(name)) continue;
      usedNotDeclared.push(name);
    }
  }
}

const ranked = (m) => [...m.entries()].sort((a, b) => b[1].count - a[1].count);
console.log(`files: ${files.length}`);
console.log('\n### ac* identifiers, by how many shader bodies use them');
console.log('name  count  files  types');
for (const [name, e] of ranked(acIds)) {
  console.log(`${name}\t${e.count}\t${e.files.size}\t${[...e.types].join('+')}`);
}
console.log('\n### sampler helpers');
for (const [name, e] of [...helpers.entries()].sort((a, b) => b[1].count - a[1].count)) {
  console.log(`${name}\t${e.count}`);
}
console.log(`\ndeclared-but-never-referenced-in-a-fragment-shader: ${declaredNotUsed.length}`);
console.log(declaredNotUsed.slice(0, 20).join('\n'));
